mapper.select:
SELECT * FROM (
    SELECT 
    FROM t_ai_message
    WHERE conversation_id = #{conversationId}
      AND visible_to_user = TRUE
      AND (#{excludeRunId} IS NULL OR run_id != #{excludeRunId})
    ORDER BY create_time DESC, id DESC
    LIMIT #{limit}
) recent_messages
ORDER BY create_time ASC, id ASC
